"use strict";

(() => {
  const VERSION = "20260823-v81-15";
  const CANONICAL = `assets/imagens/memory-mark-official-v81-15.png?v=${VERSION}`;
  const EMBEDDED = "data:image/png;base64,";

  const STYLE_ID = "memory-logo-guard-v81-15-style";

  function ensureStyle() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement("style");
    style.id = STYLE_ID;
    style.textContent = `
      .memory-topbar-brand{
        display:inline-flex!important;
        align-items:center!important;
        gap:8px!important;
      }

      .memory-topbar-brand img,
      .sidebar-brand__mark img,
      .sidebar-memory-mobile__icon img,
      [data-memory-logo-v81-15]{
        display:block!important;
        object-fit:contain!important;
        background:transparent!important;
      }

      .memory-topbar-brand img{
        width:30px!important;
        height:30px!important;
        min-width:30px!important;
        padding:3px!important;
        border-radius:9px!important;
      }

      .sidebar-brand__mark img{
        width:100%!important;
        height:100%!important;
      }

      .sidebar-memory-mobile__icon img{
        width:100%!important;
        height:100%!important;
      }

      .sidebar-brand__fallback{
        display:none!important;
      }
    `;
    document.head.appendChild(style);
  }

  function isMemoryLogo(img) {
    if (!(img instanceof HTMLImageElement)) return false;

    const src = String(img.getAttribute("src") || "");
    const alt = String(img.getAttribute("alt") || "").toLowerCase();

    return (
      img.hasAttribute("data-memory-logo-v81-15")
      || /memory-mark(?:-official)?/i.test(src)
      || Boolean(img.closest?.(".sidebar-brand__mark"))
      || Boolean(img.closest?.(".memory-topbar-brand"))
      || Boolean(img.closest?.(".sidebar-memory-mobile__icon"))
      || (
        alt === "memory"
        && Boolean(
          img.closest?.(".sidebar-brand")
          || img.closest?.(".app-topbar")
          || img.closest?.(".memory-share-preview__brand")
        )
      )
    );
  }

  function attachFallback(img) {
    if (img.dataset.memoryLogoFallbackV815 === "1") return;
    img.dataset.memoryLogoFallbackV815 = "1";

    img.addEventListener("error", () => {
      if (img.src !== EMBEDDED) {
        img.src = EMBEDDED;
      }
    });
  }

  function applyCanonical(img) {
    if (!isMemoryLogo(img)) return;

    img.setAttribute("data-memory-logo-v81-15", "1");
    attachFallback(img);

    const current = String(img.getAttribute("src") || "");

    if (
      !current.includes("memory-mark-official-v81-15.png")
      && !current.startsWith("data:image/png;base64,")
    ) {
      img.src = CANONICAL;
    }

    const fallback = img.parentElement?.querySelector?.(".sidebar-brand__fallback");
    if (fallback) fallback.style.display = "none";
  }

  function ensureTopbarLogo(root = document) {
    root.querySelectorAll?.(".memory-topbar-brand").forEach(brand => {
      let img = brand.querySelector("img");

      if (!img) {
        img = document.createElement("img");
        img.alt = "";
        img.setAttribute("data-memory-logo-v81-15", "1");
        brand.prepend(img);
      }

      applyCanonical(img);
    });
  }

  function scan(root = document) {
    ensureStyle();

    if (root instanceof HTMLImageElement) {
      applyCanonical(root);
    }

    root.querySelectorAll?.("img").forEach(applyCanonical);
    ensureTopbarLogo(root);
  }

  function refresh() {
    scan(document);

    // Segunda passagem após shells dinâmicos terminarem de montar.
    setTimeout(() => scan(document), 80);
    setTimeout(() => scan(document), 450);
  }

  const observer = new MutationObserver(records => {
    for (const record of records) {
      record.addedNodes.forEach(node => {
        if (node instanceof Element) scan(node);
      });
    }
  });

  ensureStyle();
  refresh();

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });

  window.addEventListener("pageshow", refresh, { passive: true });
  window.addEventListener("online", refresh, { passive: true });
  window.addEventListener("load", refresh, { once: true });

  window.MemoryLogoGuard = {
    version: "v81.15",
    canonical: CANONICAL,
    embedded: EMBEDDED,
    refresh
  };
})();
